-- boi:backup-tables public.news_articles
-- boi:expect-before select count(*) from public.news_articles where content like '%See live prices and stock on the [%' or content like '%Check our deals page for real-time availability.%' or content like '%A: Check our compare page for real-time Toycra stock and prices.%' or content like '%Check live prices at bricksofindia.com.%' or content like '%is listed at ₹17,999 at both MyBrickHouse and Toycra (as of 26 Sep 2026).%' = 7
-- boi:expect-after select count(*) from public.news_articles where content like '%See live prices and stock on the [%' or content like '%Check our deals page for real-time availability.%' or content like '%A: Check our compare page for real-time Toycra stock and prices.%' or content like '%Check live prices at bricksofindia.com.%' or content like '%is listed at ₹17,999 at both MyBrickHouse and Toycra (as of 26 Sep 2026).%' = 0

UPDATE public.news_articles SET content = replace(content, 'See live prices and stock on the [', 'We check prices daily. See prices and stock on the [') WHERE content LIKE '%See live prices and stock on the [%';
UPDATE public.news_articles SET content = replace(content, 'Check our deals page for real-time availability.', 'Check our deals page for availability; we check prices daily.') WHERE content LIKE '%Check our deals page for real-time availability.%';
UPDATE public.news_articles SET content = replace(content, 'A: Check our compare page for real-time Toycra stock and prices.', 'A: Check our compare page for Toycra stock and prices; we check prices daily.') WHERE content LIKE '%A: Check our compare page for real-time Toycra stock and prices.%';
UPDATE public.news_articles SET content = replace(content, 'Check live prices at bricksofindia.com.', 'Check prices at bricksofindia.com; we check them daily.') WHERE content LIKE '%Check live prices at bricksofindia.com.%';
UPDATE public.news_articles SET content = replace(content, 'is listed at ₹17,999 at both MyBrickHouse and Toycra (as of 26 Sep 2026).', 'was ₹17,999 at both MyBrickHouse and Toycra when we wrote this.') WHERE content LIKE '%is listed at ₹17,999 at both MyBrickHouse and Toycra (as of 26 Sep 2026).%';
